begin;
do $$
declare member uuid:=gen_random_uuid();staff uuid;principal uuid;op uuid:=gen_random_uuid();token_id uuid:=gen_random_uuid();rid uuid;stamp timestamptz;version timestamptz;payload jsonb;
begin
 select id into staff from public.cheongla_profiles where role='manager' and approval_status='approved' and membership_state='active' limit 1;
 select id into principal from public.cheongla_profiles where role in('owner','english_director','math_director') and approval_status='approved' and membership_state='active' limit 1;
 assert staff is not null and principal is not null,'staff fixture identities missing';
 insert into auth.users(id,email,raw_user_meta_data)values(member,'staff-recovery-'||member||'@example.invalid','{"full_name":"복구검증회원","contact_phone":"01000000994"}');
 update public.cheongla_profiles set role='student',approval_status='approved' where id=member;
 assert not has_function_privilege('authenticated','public.cheongla_manual_recovery_job(uuid,uuid,uuid,text,text,timestamptz)','execute'),'privileged job exposed';
 assert not has_function_privilege('anon','public.cheongla_manual_account(uuid)','execute'),'anonymous lookup exposed';
 perform set_config('request.jwt.claim.sub',member::text,true);
 perform set_config('request.jwt.claim.role','authenticated',true);
 begin perform public.cheongla_account_help_list();raise exception 'student queue access';exception when insufficient_privilege then null;end;
 begin perform public.cheongla_manual_account(member);raise exception 'student account lookup';exception when insufficient_privilege then null;end;
 begin perform public.cheongla_recovery_member_search('복구검증회원','01000000994');raise exception 'student search access';exception when insufficient_privilege then null;end;
 payload:=public.cheongla_request_account_help(gen_random_uuid(),token_id,'password','복구검증회원','01000000994','student','','','');
 assert payload='{"accepted":true}'::jsonb,'public response leaks matches';
 select id,updated_at into rid,stamp from cheongla_private.account_help_requests where request_token=token_id;
 assert rid is not null,'request missing';
 perform set_config('request.jwt.claim.sub',staff::text,true);
 assert cheongla_private.can_manage_account_recovery(),'manager permission missing';
 assert exists(select 1 from jsonb_array_elements(public.cheongla_account_help_list())r where r->>'id'=rid::text),'manager queue missing';
 assert exists(select 1 from jsonb_array_elements(public.cheongla_recovery_member_search('복구검증회원','01000000994'))r where r->>'id'=member::text),'manager search missing';
 payload:=public.cheongla_manual_account(member);assert payload->>'role'='student' and payload->>'phone'='01000000994','manager identity lookup failed';
 assert public.cheongla_manual_account(principal) is null,'staff target exposed';
 assert exists(select 1 from public.cheongla_notifications where recipient_id=staff and source_kind='account_recovery' and source_id=rid),'manager notification missing';
 assert cheongla_private.can_read_notification('account_recovery',rid,null),'manager notification forbidden';
 perform public.cheongla_resolve_account_help(rid,'done','검증용 본인 확인',stamp);
 assert (select resolved_by=staff and state='done' from cheongla_private.account_help_requests where id=rid),'manager resolution failed';
 begin perform public.cheongla_preview_account_merge(member,principal);raise exception 'manager merge permission expanded';exception when insufficient_privilege then null;end;
 select membership_updated_at into version from public.cheongla_profiles where id=member;
 perform set_config('request.jwt.claim.role','service_role',true);
 perform public.cheongla_manual_recovery_job(staff,member,op,'issue','가입 당시 번호 확인 검증',version);
 perform public.cheongla_manual_recovery_job(staff,member,op,'issued');
 perform set_config('request.jwt.claim.sub',member::text,true);
 assert public.cheongla_account_recovery_state() and not cheongla_private.can_use_member_services(),'temporary login bypassed password gate';
 begin update public.cheongla_profiles set approval_status='approved' where id=member;raise exception 'manual approval bypassed recovery';exception when raise_exception then if sqlerrm='manual approval bypassed recovery' then raise;end if;end;
 op:=gen_random_uuid();perform public.cheongla_manual_recovery_job(member,member,op,'finish_begin');perform public.cheongla_manual_recovery_job(member,member,op,'finish');
 assert not public.cheongla_account_recovery_state() and cheongla_private.can_use_member_services(),'new password gate completion failed';
 assert (select encrypted_password is null or encrypted_password='' from auth.users where id=member),'test changed credentials';
end $$;
rollback;
select 'PASS: manager queue/search/identity/notification/resolution and temporary recovery gate; student denial, staff target protection and merge restriction preserved; all synthetic data rolled back' as result;
